import{_ as s,o as e,c as p,a3 as r}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"较简单的自适应装置们","description":"","frontmatter":{"translationSource":{"title":"较简单的自适应装置们","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=kXUgC0EOTqKh09bVHL9EPN","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/some-simpler-adaptive-setups"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/some-simpler-adaptive-setups"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/some-simpler-adaptive-setups"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/some-simpler-adaptive-setups"}]]},"headers":[],"relativePath":"zh/some-simpler-adaptive-setups.md","filePath":"zh/page-kXUgC0EOTqKh09bVHL9EPN.md"}'),n={name:"zh/some-simpler-adaptive-setups.md"};function i(o,a,l,c,d,t){return e(),p("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="较简单的自适应装置们" tabindex="-1">较简单的自适应装置们 <a class="header-anchor" href="#较简单的自适应装置们" aria-label="Permalink to &quot;较简单的自适应装置们&quot;">​</a></h1><blockquote><p>源页面 ID：<code>kXUgC0EOTqKh09bVHL9EPN</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=kXUgC0EOTqKh09bVHL9EPN" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>咕咕咕 咕咕 咕咕咕咕咕</p><p>言正在施工中......</p><p>旨在由浅入深地讲解1.4版本中我们设计&amp;主要使用的自适应装置。<span class="mark-red">请按照装置顺序阅读。</span></p><p>另外由于笔者过于熟悉下列装置，难免有囿于自身视角的表述，若有不解之处请积极评论。</p><p>~~kokobird评论：猪吓哭……~~不要劝退读者啊老大TAT</p><p>斯改：请保持更新，这是我了解先进自适应的唯一方式（言：先进在哪...</p><p>kokobird:老大，我才想起来之前我帮你发的那个视频里面你已经剪了很多装置的讲解了，你看看放在哪里合适 BV1CX3J6ZEhc</p><p>JNK:须知前后馈是防止浪费，使得反应可以量化为标准的配方的方法</p><p>kokobird：老大，我写好了这节，里面介绍了激活物问题的起因，研发过程以及前馈后馈的概念<a href="/endfield-skydoc/zh/3-3-you-you-xiranite-freeloading-pig">3.3 你……你这头白吃息壤的猪！</a></p><p><span id="source-block-pn4Iehl7uCFHMbdr1hj0r1"></span></p><h2 id="息壤气-液气机-前馈-反馈控制" tabindex="-1">息壤气 液气机-前馈-反馈控制 <a class="header-anchor" href="#息壤气-液气机-前馈-反馈控制" aria-label="Permalink to &quot;息壤气 液气机-前馈-反馈控制&quot;">​</a></h2><p>生产配方：1液化息壤（激活）+5液化息壤=5息壤气</p><p>P.S. 虽然机器UI上激活物部分显示“最低速率6单位/min”但是实际的作用方式是每个激活物使机器运转10s，造成激活物浪费的情况有且仅有三种：①机器运转时原料不足②机器运转时产物阻塞③存在两个激活物进入间隔小于10s</p><p>前馈：由原料输入速率决定机器运行速率</p><p>反馈控制：原料溢出时机器高速率运行，原料不溢出时机器低速率运行</p><p>P.S. 第一次阅读时不明白前馈后馈、比例控制反馈控制什么的没关系，请先继续阅读，结合实际的机器慢慢理解这些分类。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a55f5a44821fbabd.q90-6cd1ff8531b46ce8.webp" alt="较简单的自适应装置们"></p><p>由于图中所示的“多口暗管-管道汇流器”造成的优先级（<a href="/endfield-skydoc/zh/input-output-merge-priority-theory">优先输入/输出/汇入理论简要说明</a>），液化息壤会先进入机器的原料入口并填满机器后才会开始进入激活入口。<u>也就是说，当有激活物进入机器时一定有充足原料，</u>此时只要满足产物不堵（产生的息壤气都被下游产线消耗干净了）并且激活物输入速率不超过6/min（通过准入口限速6/min可以轻松实现），就一定不会有激活物被浪费。</p><p>在本装置中，原料也就是液化息壤溢出时有液化息壤进入激活入口，使得机器高速率（30/min）运行，若输入液化息壤速率小于36/min此时消耗原料直到液化息壤不再溢出到多口暗管出口；而当液化息壤未溢出到多口暗管出口时将没有液化息壤进入激活入口，使得机器低速率（0/min）运行，此时若输入液化息壤速率大于0/min就会积累原料直至原料溢出到多口暗管出口，如此循环往复使得<u>足够长的时间后装置中缓存的液化息壤既不增加也不减少</u>（缓存在这里可以简单理解为装置中留有的液化息壤的量），<u>这就是所谓的“反馈控制”了。</u><span class="mark-grey">或者说在原料输入为0/min-36/min时：原料溢出→加速运行→原料不溢出→减速运行→原料溢出，如此这般循环往复。</span></p><p>在本装置中，由于“足够长的时间后装置中缓存的液化息壤既不增加也不减少”，从输入原料速率的角度来看就是输入原料速率等于机器消耗原料速率，也就是输入原料速率控制机器运行速率；如果从具体的运行流程出发的话，激活入口每进入1液化息壤就因为机器中一定有充足原料而一定消耗5液化息壤，需要再往原料入口中输入5液化息壤才能再往激活入口输入液化息壤，那么这台液气机的实际反应速率（息壤气产率）就是（原料输入速率v1）：v1/(5+1)*5 ，（从左到右的 5 1 5 分别是 往原料入口输入5液化息壤 往激活入口输入1液化息壤 产生5息壤气），也可以发现机器运行速率由原料输入速率控制。<u>这就是所谓的“前馈”了。</u></p><p>看到这里你可能觉得上面这两段绕来绕去在讲废话，这是因为这台装置足够简单才显得表述比较多余，如果后文产生对“前馈”与“反馈控制”乃至于“后馈”的困惑时，不妨回到这里以此处简单的情形对更复杂的情况举一反三。</p><p><span class="mark-grey"><em>另外图中的多口暗管出口有标注“避免连接多口暗管入口”，这是因为多口连多口允许2-4/s的液气输送，而“多口暗管-管道汇流器”的优先级结构是让流量大于2/s的部分进入次优先的管道，这使得优先级不完全。举个例子，某多口连多口的实时流量是“1/s持续1s 2/s持续1s 3/s持续1s”，那么平均流量是2/s，理应没有任何物品进入“多口暗管-管道汇流器”的优先级结构中的次优先的管道，但实际上在“3/s持续1s”中是持续1s的2/s进入优先的管道而1/s进入次优先的管道，次优先的管道意外进入了1/3/s的物品！而单口多口相连就直接将流速限制在2/s，使得该优先级结构为完全的优先级。</em></span></p><p><span class="mark-grey"><em>暂且称为多口暗管-汇流器优先级的输入相位问题，后文将简称为相位问题。</em></span></p><p><span id="source-block-jbMtAzUgYuD80KP2VIIVHK"></span></p><h2 id="息壤气-液气机-前馈-比例控制" tabindex="-1">息壤气 液气机-前馈-比例控制 <a class="header-anchor" href="#息壤气-液气机-前馈-比例控制" aria-label="Permalink to &quot;息壤气 液气机-前馈-比例控制&quot;">​</a></h2><p>生产配方：1液化息壤（激活）+5液化息壤=5息壤气</p><p>前馈：由原料输入速率决定机器运行速率</p><p>比例控制：直接控制原料和激活物的比例为5：1</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0cbc497c2d640327.q90-f746202a544dbbbb.webp" alt="较简单的自适应装置们"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7c3868649842b066.q90-39a7aee217dabc0e.webp" alt="较简单的自适应装置们"></p><p><span class="mark-grey"><em>使用时需在输入端限制流量为36/min（实际流量可低于36/min），或在液气转化剂激活口处限制6/min流量。</em></span></p><p>如图所示的分流结构使得进入原料入口的液化息壤是进入激活入口的五倍，作为原料和激活物相同的配方，<u>这是最简单的比例控制的情形。</u>同时，不难看出激活物输入和原料输入比例固定也就是前者由后者控制，自然的，产物产出速率/机器运行速率就由原料输入速率控制了，<u>也就是“前馈”。</u></p><p><span id="source-block-rt7NWQgIE6noUMh21BwgbG"></span></p><h2 id="赤铜气-液气机-前馈-反馈控制" tabindex="-1">赤铜气 液气机-前馈-反馈控制 <a class="header-anchor" href="#赤铜气-液气机-前馈-反馈控制" aria-label="Permalink to &quot;赤铜气 液气机-前馈-反馈控制&quot;">​</a></h2><p>生产配方：1液化息壤（激活）+10赤铜溶液=5气态赤铜</p><p>前馈：由原料输入速率决定机器运行速率</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a495052c431e36ec.q90-2594755ba20cb8f0.webp" alt="较简单的自适应装置们"></p><p>由于图中所示的“管道汇流器-管道分流器”造成的优先级（<a href="/endfield-skydoc/zh/input-output-merge-priority-theory">优先输入/输出/汇入理论简要说明</a>），<u>当输入的</u><span class="mark-red"><u>赤铜溶液</u></span><u>处于30/min-60/min时，</u><span class="mark-red">赤铜溶液</span>会先填满机器后息壤溶液才会提高进入激活入口的速率，由3/min增加到6/min。也就是说，当有激活物进入机器时一定有充足原料，此时只要满足产物不堵（产生的<span class="mark-red">气态赤铜</span>都被下游产线消耗干净了）并且激活物输入速率低于6/min（通过准入口限速6/min可以轻松实现），就一定不会有激活物被浪费。</p><p><u>那么为什么输入30/min-60/min的</u><span class="mark-red"><u>赤铜溶液</u></span><u>时能确保激活物进入机器时一定有充足原料呢？</u>当<span class="mark-red">赤铜溶液</span>填满机器并满溢到暗管缓存（即保持阻塞）时汇流器只接受优先输入的<span class="mark-red">赤铜溶液</span>而<span class="mark-green">液化息壤</span>无法进入，也就是阻断了<span class="mark-green">液化息壤</span>的回流——而<span class="mark-green">液化息壤</span>不回流时6/min的<span class="mark-green">液化息壤</span>全部输入激活入口，此时消耗60/min<span class="mark-red">赤铜溶液</span>，若<span class="mark-red">赤铜溶液</span>输入小于60/min则装置中的<span class="mark-red">赤铜溶液</span>逐渐减少直到不再占满汇流器，于是<span class="mark-green">液化息壤</span>可以正常回流，输入激活入口的<span class="mark-green">液化息壤</span>变回3/min，此时消耗30/min<span class="mark-red">赤铜溶液</span>，若<span class="mark-red">赤铜溶液</span>输入大于30/min则装置中的<span class="mark-red">赤铜溶液</span>逐渐增加直到再次占满汇流器阻塞<span class="mark-green">液化息壤</span>的回流，如此循环往复使得<u>足够长的时间后装置中缓存的</u><span class="mark-red"><u>赤铜溶液</u></span><u>既不增加也不减少</u>——当然，同样的做法可以用于重息壤/赫铜/灼铜固化，毕竟区别只是替换原料和激活物。<u>那么这就是原料和激活物不同的装置的“反馈控制”了。</u><span class="mark-grey">或者说在原料输入不满30/min时：原料溢出→加速运行→原料不溢出→减速运行→原料溢出，如此这般循环往复。</span></p><p>由于“足够长的时间后装置中缓存的<span class="mark-red">赤铜溶液</span>既不增加也不减少”，从输入原料速率的角度来看就是输入原料速率等于机器消耗原料速率，<u>即输入原料速率控制机器运行速率也就是“前馈”了。</u></p><details><summary>给言老大送总结图——kokobird</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6cb259b335e2794b.q90-efb40c42f28b1f4e.webp" alt="较简单的自适应装置们"></p></details><details><summary>给言老大送视频讲解——kokobird</summary><p>【【终末地/1.5基建】模块蓝图与技术讲解，120息壤+150铜=18.4息壤液+零浪费赫铜重息壤】 【精准空降到 07:09】 <a href="https://www.bilibili.com/video/BV1Jbt66XECE/?share_source=copy_web&amp;vd_source=ff7e542929960451adc95a08b74266a8&amp;t=429" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Jbt66XECE/?share_source=copy_web&amp;vd_source=ff7e542929960451adc95a08b74266a8&amp;t=429</a></p></details><p>接下来是该装置的拓展内容，初次阅读可以跳过，当然也看一看是最好的。</p><p><span id="source-block-WWzr4gcf9ltyV0vuFEpITK"></span></p><h3 id="稍加修改降低30-min的安全输入下限至20-min" tabindex="-1">稍加修改降低30/min的安全输入下限至20/min <a class="header-anchor" href="#稍加修改降低30-min的安全输入下限至20-min" aria-label="Permalink to &quot;稍加修改降低30/min的安全输入下限至20/min&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-18fbd62ae95e8119.q90-413cea65509c4e6f.webp" alt="较简单的自适应装置们"></p><p>如图所示，让分流器的两个输出口（图中高亮）进行回流，也就是回流不被阻塞时输入激活入口的液化息壤为6/3/min，此时赤铜溶液输入大于20/min即可不浪费息壤液地运行。</p><p><span id="source-block-yspmniCYNV6aoreECUDXoH"></span></p><h3 id="复用分流器来省下管道元件" tabindex="-1">复用分流器来省下管道元件 <a class="header-anchor" href="#复用分流器来省下管道元件" aria-label="Permalink to &quot;复用分流器来省下管道元件&quot;">​</a></h3><p>息壤液分流需要分流器，优先级形成需要分流器，为什么不能复用呢？（复用的分流器高亮）于是产生以下结构：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c5da20802ab18b58.q90-83d976fcaf6fa85c.webp" alt="较简单的自适应装置们"></p><p><span class="mark-grey"><em>然而因为用于</em></span><span class="mark-green"><em>息壤液</em></span><span class="mark-grey"><em>分流的分流器紧贴汇流器放置，中间缺乏缓存，如果通过混管的原料过多容易出现息壤液回流被更多地阻塞，在某些输入的情况中会发生明明处于50-100%的安全输入区间却无法积累原料造成机器空烧。不过绝大部分情况下这并不会发生。</em></span></p><p><span id="source-block-GPVuKVjXpjJwV8QY13uNbW"></span></p><h3 id="使用溢流结构消灭安全输入下限" tabindex="-1">使用溢流结构消灭安全输入下限 <a class="header-anchor" href="#使用溢流结构消灭安全输入下限" aria-label="Permalink to &quot;使用溢流结构消灭安全输入下限&quot;">​</a></h3><p>使用溢流使得安全输入下限为0，优点十分显著，缺点是更高的元件数、更大的占地</p><p><span id="source-block-ld1GQm5eap1zGMtEv5FfUf"></span></p><h3 id="结合息壤液总线简化溢流结构" tabindex="-1">结合息壤液总线简化溢流结构 <a class="header-anchor" href="#结合息壤液总线简化溢流结构" aria-label="Permalink to &quot;结合息壤液总线简化溢流结构&quot;">​</a></h3><p>省去了溢流结构的优先汇入，转而让总线对上游轮询获得广义上的优先汇入，减少了管道件用量和占地。</p><p><span id="source-block-0XgKNhUGDp6ohb2XKS7ItQ"></span></p><h3 id="输入震荡带来的隐患" tabindex="-1">输入震荡带来的隐患 <a class="header-anchor" href="#输入震荡带来的隐患" aria-label="Permalink to &quot;输入震荡带来的隐患&quot;">​</a></h3><p>我们假设一种输入形式，x秒输入10/min后x秒输入60/min，平均输入速率即35/min处于安全区间，但是如果这个x足够大以至于在输入10/min的x秒时机器用光了装置中所有原料，就会发生息壤液空烧而浪费。所以上游若存在震荡需要多多注意会不会有这样的隐患，若有必要可以增加缓存或者对输入整流/滤波。一种简单的整流器（将）如下：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6008cd20ad06a7a1.q90-b6a70f85caad1e46.webp" alt="较简单的自适应装置们"></p><div class="logistics-image-caption" data-source-block="bqnQwrYwA0VV3L5RwHAnNp"><p>空转的话酸会跑到外面去，需要加准入口或者确保里面有其他液体</p></div><p>kokobird：四核<span class="mark-red">灼铜</span>就是一个典型雷霆例子，每次<span class="mark-red">赫铜气</span>满时，由于<span class="mark-yellow">酸气</span>溢流到<span class="mark-red">灼铜气</span>开始生产有延时，总会溢出八九个<span class="mark-yellow">酸气</span>，但是一个<span class="mark-yellow">酸气</span>就能让四核<span class="mark-red">灼铜</span>跑10秒，持续运行一分多钟的消耗很恐怖，甚至单口暗管供<span class="mark-red">赫铜气</span>可能供不过来，然后这段时间产生的<span class="mark-red">灼铜气</span>速度也很夸张，产出的速度甚至大于下游固化的速度，导致固化用的<span class="mark-green">息壤气</span>一直溢流，这些<span class="mark-green">息壤气</span>在<span class="mark-red">灼铜气</span>生产完成后还会吃掉几百个<span class="mark-red">灼铜气</span>，所以需要在<span class="mark-red">灼铜气</span>固化前加储气罐</p><p><span id="source-block-GpAMDqu6wRWBWak2xiqhpC"></span></p><h3 id="控制隔离与断电反应池代替混管" tabindex="-1">控制隔离与断电反应池代替混管 <a class="header-anchor" href="#控制隔离与断电反应池代替混管" aria-label="Permalink to &quot;控制隔离与断电反应池代替混管&quot;">​</a></h3><p><span id="source-block-vOUgIKsx6J4Hs9rAMRIMIM"></span></p><h2 id="多种流体比例控制概述" tabindex="-1">多种流体比例控制概述 <a class="header-anchor" href="#多种流体比例控制概述" aria-label="Permalink to &quot;多种流体比例控制概述&quot;">​</a></h2><p>本小节主要是kokobird写</p><p><span class="mark-grey"># 言：算是灌拆的前置知识，当然不完全用于灌拆；如果仅希望学习液气控制可以先跳过——但是因为流量复制还是会用到的，所以早晚得回来（？）</span></p><p>对于单种流体，比如液化息壤取1/5用来激活液气机，或者息壤气取1/11用来固化提纯的重息壤，直接用分汇流结构就可以了。但是，如果原料和激活物是两种流体，想让两种流体之间也形成A经过10个，B经过1个的控制关系，就需要采用额外的手段。</p><p>总体上来说，因为待检测的信号经过检测后还需要还给原产线，这部分的方案基本都是使用了信号复制。可以理解为一种“拓印”，先放一块拓印板，经过X个A物品后，板上留下X个空格，然后再拿这块板去接收X个B物品。我们主要做的就是使用游戏内机制去造出这种拓印板。</p><p><span id="source-block-ZRO4iuJDMSiB0HnEkMTg51"></span></p><h3 id="基于灌拆的前馈方案-仅限同物态-要么都是液体要么都是气体" tabindex="-1">基于灌拆的前馈方案（仅限同物态，要么都是液体要么都是气体） <a class="header-anchor" href="#基于灌拆的前馈方案-仅限同物态-要么都是液体要么都是气体" aria-label="Permalink to &quot;基于灌拆的前馈方案（仅限同物态，要么都是液体要么都是气体）&quot;">​</a></h3><p>以下是控制<span class="mark-green">液化息壤</span>：<span class="mark-rose_red">赤铜气</span>为1：10的方案。<span class="mark-rose_red">赤铜溶液</span>从右上角暗管出口流出，一半流量直接进入转化机，另一半流量进入灌装机进行检测。灌装机中空瓶充足，每有<span class="mark-rose_red">一个赤铜溶液</span>输入，就会灌装一瓶<span class="mark-rose_red">赤铜液</span>。<span class="mark-rose_red">瓶装赤铜液</span>随即进入下一个拆解机，取出这一个溶液，将其还回到液气转化机中。</p><p>对这滴<span class="mark-rose_red">赤铜液</span>来说，它只是多走了一段路而已。那么什么变化了呢？拆解机输出了一个瓶子！由于此处拆解机连了五路出口，四路直接连回到放瓶子的箱子，一路瓶子进入了装满了<span class="mark-green">液！化！息！壤！</span>的灌装机，取出一滴<span class="mark-green">液化息壤</span>，再送进拆解机。回想一下，每有一个这样的瓶子，就说明有五个瓶子从拆解机出去，就说明有五滴<span class="mark-rose_red">赤铜溶液</span>进入了灌装机，就说明总共暗管出口流出了十滴<span class="mark-rose_red">赤铜溶液</span>。因此，每出10滴<span class="mark-rose_red">赤铜溶液</span>，就会正好有1滴<span class="mark-green">液化息壤</span>进入液气转化机，实现精确的按需供给。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f31fa73eee44395e.q90-649c02c1e781149b.webp" alt="较简单的自适应装置们"></p><p>更多例子可以参考<a href="https://www.bilibili.com/video/BV1yp3q6GEK3/?share_source=copy_web&amp;vd_source=3b974227efd90987cb6375fbe49d61b8&amp;t=393" target="_blank" rel="noreferrer">我的1.4自动配平方案视频</a>，主要包括赤铜液前馈（检测赤铜液），灼铜固化前馈（检测赫铜气）与酸气（检测赫铜气）的反馈装置。</p><p>由于拆灌机比较耗电，占地也大，后续大家基本都用本页面中的其他机制结构进行控制了。不过就我看来，拆灌比例控制方案可能还是对新手来说最容易理解的。<s>另外不需要特别多管道件，还自带五分器，并且不依赖于优先级，运转像齿轮咬合般精确，响应速度较快，震荡幅度小<br> 言：真的假的，像我这种1.4刚回坑的看到这个固体流量复制结构其实直接吓晕过去了</s></p><p><span id="source-block-7wWfjywD6y5qN3j05ZbtZr"></span></p><h3 id="基于灌拆的后馈方案-可以不同物态" tabindex="-1">基于灌拆的后馈方案（可以不同物态） <a class="header-anchor" href="#基于灌拆的后馈方案-可以不同物态" aria-label="Permalink to &quot;基于灌拆的后馈方案（可以不同物态）&quot;">​</a></h3><p>讲解同样见上面的视频，由智乃佬开发，把罐子和瓶子按5：1混带，每走一个酸气就会灌装一个酸气，同时让混带推进一格。走五格之后瓶子就会去灌装1滴液化息壤，生产5个酸气。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d47bce58da88599f.q90-09aaab70a6e328bd.webp" alt="较简单的自适应装置们"></p><p><span id="source-block-UxB6wgFGoOINnRzbFQRMRY"></span></p><h3 id="基于流体回路空位的方案" tabindex="-1">基于流体回路空位的方案 <a class="header-anchor" href="#基于流体回路空位的方案" aria-label="Permalink to &quot;基于流体回路空位的方案&quot;">​</a></h3><p>跟B站@花底月莺讨论了一下，这种方法也ok~~ 其实我最早就想做这种方案，但是测试的时候发现数量不对就没用，现在看来应该是四卡一的问题~~</p><p>和固体磁带法其实类似，使用液体版本。找一个第三种液体做循环回路（图中水），在储液罐下游，先跟待检测的液体（图中液化息壤）合并后分离，再下游和待输出的液体（图中污水）合并后分离。液化息壤把水卡出多少个空位就有多少个空位能容纳污水输出。图中红色箭头为优先级方向。</p><p>需要注意的是这套装置容易出现四卡一<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a>，投入使用前最好先测速流体回路速度是不是120（图中底部两个测速器，实际上一根管子连接就行）</p><p>@花底月莺用这种方案做的三核重息壤自适应产线，根据输入的气矿多少自适应的消耗液化息壤来给固气机生产重息壤，重息壤爆仓时停机。最大接收150气矿来达到3核重息壤的产速<a href="https://www.xiaoheihe.cn/app/bbs/link/74ee7297d34d" target="_blank" rel="noreferrer">小黑盒链接</a></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-63b0f1ebe5aac74d.q90-d417f1877418ee4f.webp" alt="较简单的自适应装置们"></p><p><span id="source-block-KQMwH9m91p61ZbV7SIdCQF"></span></p><h2 id="重息壤-固气机-前馈-比例控制" tabindex="-1">重息壤 固气机-前馈-比例控制 <a class="header-anchor" href="#重息壤-固气机-前馈-比例控制" aria-label="Permalink to &quot;重息壤 固气机-前馈-比例控制&quot;">​</a></h2><p>两种方案：</p><p>控制重息壤气 息壤气5：1，主要使用流量复制（见于<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups#source-block-vOUgIKsx6J4Hs9rAMRIMIM">较简单的自适应装置们</a>），早期的灌拆则是因为液气流量复制技术不成熟而将问题转化为固体的流量复制</p><p>直接控制息壤气分流10：1，取巧但有效</p><p><span id="source-block-QT0CJjZ3t6r0Vuy48ELcl6"></span></p><h2 id="重息壤-固气机-前馈-反馈控制" tabindex="-1">重息壤 固气机-前馈-反馈控制 <a class="header-anchor" href="#重息壤-固气机-前馈-反馈控制" aria-label="Permalink to &quot;重息壤 固气机-前馈-反馈控制&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4d8a6b88cbfa7753.q90-dc33d0fa7ee2b41b.webp" alt="较简单的自适应装置们"></p><p>生产配方：1息壤气（激活）+10息壤气（被提纯为10重息壤气）=2重息壤 <span class="mark-grey">#惰气环境/分离芯充足</span></p><p>前馈：由原料输入速率决定机器运行速率</p><p>反馈控制：原料溢出时机器高速率运行，原料不溢出时机器低速率运行</p><p>将一组提纯机-固气机当成“一台液气机”，那原理就和此篇一模一样了<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups#source-block-pn4Iehl7uCFHMbdr1hj0r1">较简单的自适应装置们</a>。</p><p>所以依旧是<u>当有激活物进入“一台液气机”时一定有充足原料，</u>此时只要满足产物不堵（产生的息壤气都被下游产线消耗干净了）并且激活物输入速率不超过6/min（通过准入口限速6/min可以轻松实现），就一定不会有激活物被浪费。</p><p>在原料输入为0/min-36/min时：原料溢出→加速运行→原料不溢出→减速运行→原料溢出，如此这般循环往复，<u>是反馈控制的体现。</u></p><p>不难看出产出速率由输入速率控制，<u>是前馈的体现。</u></p><p>当然了，<strong>相位问题</strong>在这里也存在，图中多口暗管出口须与单口暗管入口连接，详见<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups">较简单的自适应装置们</a>。</p><p><span id="source-block-ckClPl3A1wZT5aMlXRFkvh"></span></p><h3 id="把两组提纯-固气视为-一台液气机" tabindex="-1">把两组提纯-固气视为“一台液气机” <a class="header-anchor" href="#把两组提纯-固气视为-一台液气机" aria-label="Permalink to &quot;把两组提纯-固气视为“一台液气机”&quot;">​</a></h3><p>既然可以把一组提纯-固气视为一台液气机，那两组呢？当然也是可以的。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-814afa5d6120e1f9.q90-155173a599b14e17.webp" alt="较简单的自适应装置们"></p><p>此时的生产配方可以视为：</p><p>2息壤气（激活）+20息壤气（被提纯为10重息壤气）=4重息壤 <span class="mark-grey">#惰气环境/分离芯充足</span></p><p>当然别忘了<strong>相位问题</strong>，与先前不同的是单口暗管只能最多传输120/min物品，使得图中多口暗管出口最多得到120/min的息壤气输入。我们知道一组提纯-固气最多支持66/min的息壤气生产为重息壤（66/min=60/min（重息壤气生产）+6/min（固气机激活）），那两组其实应该能接受132/min的息壤气生产为重息壤，如果只能输入120/min息壤气的话岂不是在息壤气足够时不能完全利用机器生产力吗？</p><p>研发人员深度思考中...</p><p><span id="source-block-Wi0XahCYOfQzZbiJEKVEQI"></span></p><h3 id="把更大的结构也视为-一台液气机" tabindex="-1">把更大的结构也视为“一台液气机” <a class="header-anchor" href="#把更大的结构也视为-一台液气机" aria-label="Permalink to &quot;把更大的结构也视为“一台液气机”&quot;">​</a></h3><p>如果起点不是息壤气而是液化息壤，</p><p><span id="source-block-ZCNK3cAsSj0evFP4vunpsX"></span></p><h2 id="灼铜-多核固气机-前馈-反馈控制" tabindex="-1">灼铜 多核固气机-前馈-反馈控制 <a class="header-anchor" href="#灼铜-多核固气机-前馈-反馈控制" aria-label="Permalink to &quot;灼铜 多核固气机-前馈-反馈控制&quot;">​</a></h2><p>将多个设备视为一个整体，比如将三核固气视为至多消耗原料灼铜气90/min和激活物息壤气18/min的单个机器，然后接入反馈控制模块。</p><p>并确保低运行速率时原料积累——没有直连控制模块的核的消耗量要小于等于直连控制模块的核的消耗量，在息壤气通入三核的三个激活物入口采用均分时可以认为没有直连控制模块的核的输入量要大于等于直连控制模块的核的输入量（当然可以不均分，保证消耗量如上文所说，但是在三核的情境里不均分也不会更省管道件了）；同时也要避免因为流经控制模块的原料流量过大且采取分流器复用而造成实际下限升高，即直连核数为2/2或者1或者1/2（更低则无意义）此处直连核数为1</p><p><span id="source-block-nGCCd7T8zJ0hIFpUm3u04B"></span></p><h2 id="灼铜气-多核气体反应炉-前馈-反馈控制" tabindex="-1">灼铜气 多核气体反应炉-前馈-反馈控制 <a class="header-anchor" href="#灼铜气-多核气体反应炉-前馈-反馈控制" aria-label="Permalink to &quot;灼铜气 多核气体反应炉-前馈-反馈控制&quot;">​</a></h2><p>在息壤气供应充足的前提下，将三核气反视为至多消耗原料赫铜气180/min和激活物酸气6/min的单个机器</p><p>并确保低运行速率时原料积累——没有直连控制模块的核的消耗量要小于等于直连控制模块的核的消耗量，因为酸气散布机对三个气反的控制完全一致所以可以直接认为没有直连控制模块的核的输入量要大于等于直连控制模块的核的输入量；同时也要避免因为流经控制模块的原料流量过大且采取分流器复用而造成实际下限升高，即直连核数为2/2或者1或者1/2（更低则无意义）此处直连核数为1</p><p><span id="source-block-dRiqji5Pa4BrTG607tnesV"></span></p><h2 id="酸气-液气机-后馈-反馈控制" tabindex="-1">酸气 液气机-后馈-反馈控制 <a class="header-anchor" href="#酸气-液气机-后馈-反馈控制" aria-label="Permalink to &quot;酸气 液气机-后馈-反馈控制&quot;">​</a></h2><p>保持充足酸气供应并不浪费息壤液，可能是毛产中唯一刚需后馈的地方（其实不然，后面会讲到巧妙的方式避开<br> 优先走酸气，溢出的酸气将阻塞激活物息壤液进入激活入口</p><p><span id="source-block-HUDwTTEVX7SMgbBJJ5qB31"></span></p><h3 id="酸气-液气机-前后与馈-反馈控制" tabindex="-1">酸气 液气机-前后与馈-反馈控制 <a class="header-anchor" href="#酸气-液气机-前后与馈-反馈控制" aria-label="Permalink to &quot;酸气 液气机-前后与馈-反馈控制&quot;">​</a></h3><p>让息壤液流入前馈的反馈控制模块前先经过后馈的反馈控制模块即实现与逻辑，即仅允许息壤液在原料充足且产物不阻塞时进入激活入口。</p><p>前馈部分当然可以选择100%自适应的溢流式。</p><p>没错，对酸气来说这毫无必要——事实上这里给出的是原料 产物 激活物均不同时的前后与馈的通用方案。</p><p><span id="source-block-927DmCsBL8fp8fjP6fISM4"></span></p><h2 id="赤铜气-多核液气机-后馈-反馈控制" tabindex="-1">赤铜气 多核液气机-后馈-反馈控制 <a class="header-anchor" href="#赤铜气-多核液气机-后馈-反馈控制" aria-label="Permalink to &quot;赤铜气 多核液气机-后馈-反馈控制&quot;">​</a></h2><p>前馈能多核，后馈也一样，把多核视为一个机器</p><p><span id="source-block-zmBKtZ8iUEhQ3VyLjCLk3M"></span></p><h3 id="赤铜气-多核液气机-前后与馈-反馈控制" tabindex="-1">赤铜气 多核液气机-前后与馈-反馈控制 <a class="header-anchor" href="#赤铜气-多核液气机-前后与馈-反馈控制" aria-label="Permalink to &quot;赤铜气 多核液气机-前后与馈-反馈控制&quot;">​</a></h3><p>多核当然也能做前后馈的与逻辑了，视为一个机器然后接入前后与馈的控制模块</p><p><span id="source-block-MWuvhZkwIaZ3JRFUIkZKwO"></span></p><h3 id="隔离控制-集中控制-均分控制" tabindex="-1">隔离控制？集中控制！均分控制！？ <a class="header-anchor" href="#隔离控制-集中控制-均分控制" aria-label="Permalink to &quot;隔离控制？集中控制！均分控制！？&quot;">​</a></h3><p>如果用以下结构则反馈过程从机器的“原料溢出→加速运行→原料不溢出→减速运行→原料溢出”循环变为多口暗管加上机器的“原料溢出→加速运行→原料不溢出→减速运行→原料溢出”循环，可支持流量显然达到240/min，由此可以接入更多核，也就是隔离控制天然适合集中控制多核。<br> 那240就是上限吗？当然不！参考多核固气多核液气中的反馈结构，为了避免流量过高而无法使用分流器复用，流经控制模块的只是一部分的机器接受的输入，同理我们可以将多个240中调取比如30汇流后流经隔离控制模块，就能对所有模块实施均分控制，也就是说实际上一个控制模块能控制120/min激活物以内的核数，当然比120/min激活物更多也是可以的但是这个需求在可预见的未来中有点不太可能（1200赤铜溶液输入，加上显然存在的固体赤铜使用，比谷地的蓝矿还多得多）</p><p><span id="source-block-no8mFWFgz8MM6gUqsnmvdE"></span></p><h2 id="酸气-液气机-后馈-比例控制" tabindex="-1">酸气 液气机-后馈-比例控制 <a class="header-anchor" href="#酸气-液气机-后馈-比例控制" aria-label="Permalink to &quot;酸气 液气机-后馈-比例控制&quot;">​</a></h2><p>通过阻塞控制产物和激活物五比一，优雅的设计，但是不能简单地做成隔离控制乃至集中控制</p><p><span id="source-block-X55F4HMCEWgz89R3mKCyU8"></span></p><h2 id="酸气-混用满速息壤气液气机-后馈-比例控制" tabindex="-1">酸气 混用满速息壤气液气机-后馈-比例控制 <a class="header-anchor" href="#酸气-混用满速息壤气液气机-后馈-比例控制" aria-label="Permalink to &quot;酸气 混用满速息壤气液气机-后馈-比例控制&quot;">​</a></h2><p>注意到产出酸气和输入酸液的比例是一比一，为什么不用酸气使用来控制酸液输入呢？如此简洁</p><p><span id="source-block-DGOeQqsHhmKgbM8QjjJGki"></span></p><h3 id="混用满速赤铜气液气机-后馈-比例控制" tabindex="-1">混用满速赤铜气液气机-后馈-比例控制 <a class="header-anchor" href="#混用满速赤铜气液气机-后馈-比例控制" aria-label="Permalink to &quot;混用满速赤铜气液气机-后馈-比例控制&quot;">​</a></h3><p>混息壤和混赤铜其实区别不大，需要注意的只有赤铜液是两滴两滴反应，需要有额外输入保证不会卡在机器中仅一滴铜然后机器睡觉</p><p><span id="source-block-AiiZV7HBrHkNnZ4FrUFOaG"></span></p><h3 id="混用不满速息壤气液气机-后馈-比例控制" tabindex="-1">混用不满速息壤气液气机-后馈-比例控制 <a class="header-anchor" href="#混用不满速息壤气液气机-后馈-比例控制" aria-label="Permalink to &quot;混用不满速息壤气液气机-后馈-比例控制&quot;">​</a></h3><p>那一定要满速吗？无论机器反应酸气还是反应息壤都会反映到息壤液溢出上（因为酸气足够少，如果酸气需求足够多的话就是下面的灼重混固气的双料自适应结构了。尽管如此为了避免部分方案（比如最大净产出）震荡，事实上也可以考虑这么做），所以让溢出的息壤液顺理成章成为激活物就可以混不满速了。</p><p><span id="source-block-If0ndoaEGze9w3F70BvQBw"></span></p><h3 id="混用满速息壤气液气机-前馈-例外" tabindex="-1">混用满速息壤气液气机-前馈-例外 <a class="header-anchor" href="#混用满速息壤气液气机-前馈-例外" aria-label="Permalink to &quot;混用满速息壤气液气机-前馈-例外&quot;">​</a></h3><p>一比一控制还是太吃管道件了，整整两个！那么让三核气反直接反馈酸液，酸液直接混机变成酸气后进入三核气反如何呢？这种做法甚至直接杀死了酸气的后馈需求，缺点是气反的反馈响应多少会慢点</p><p><span id="source-block-mBB5twcVdkPuz0o2apJEZz"></span></p><h3 id="混用不满速息壤气液气机-前馈-例外" tabindex="-1">混用不满速息壤气液气机-前馈-例外 <a class="header-anchor" href="#混用不满速息壤气液气机-前馈-例外" aria-label="Permalink to &quot;混用不满速息壤气液气机-前馈-例外&quot;">​</a></h3><p>那一定要满速吗？总之同上。</p><p><span id="source-block-8Q1jGfLgKGQRMQyzcj5kZy"></span></p><h2 id="重息壤-混用满速灼铜固气机-前馈-反馈控制" tabindex="-1">重息壤 混用满速灼铜固气机-前馈-反馈控制 <a class="header-anchor" href="#重息壤-混用满速灼铜固气机-前馈-反馈控制" aria-label="Permalink to &quot;重息壤 混用满速灼铜固气机-前馈-反馈控制&quot;">​</a></h2><p>灼气过量 重息壤最多25</p><p><span id="source-block-k1drcAjTKyWtJyNkZTpUDk"></span></p><h3 id="双原料自适应" tabindex="-1">双原料自适应 <a class="header-anchor" href="#双原料自适应" aria-label="Permalink to &quot;双原料自适应&quot;">​</a></h3><p>双料自适应就是让两个原料都能反馈息壤气</p><p><span id="source-block-T6EKZtC2vBfxuJjpApsqOB"></span></p><h2 id="赤铜气-固气机-前馈-反馈控制" tabindex="-1">赤铜气 固气机-前馈-反馈控制 <a class="header-anchor" href="#赤铜气-固气机-前馈-反馈控制" aria-label="Permalink to &quot;赤铜气 固气机-前馈-反馈控制&quot;">​</a></h2><p>断电反应池传递固体阻塞至液体</p><p><span id="source-block-DIFAJeoG5AObFYAxgGb3Zc"></span></p><h2 id="灼铜-固气机-后馈-反馈控制" tabindex="-1">灼铜 固气机-后馈-反馈控制 <a class="header-anchor" href="#灼铜-固气机-后馈-反馈控制" aria-label="Permalink to &quot;灼铜 固气机-后馈-反馈控制&quot;">​</a></h2><p>断电反应池传递固体阻塞至液体</p><p>本质是改变多核灼铜固气中原料的构成，并用该结构<a href="/endfield-skydoc/zh/research-on-theory-and-practice-of-complex-serial-parallel-mixed">复杂串并行混产理论与实践研究</a></p><p><span id="source-block-ITQ8P733EvTairWtUV4EBF"></span></p><h3 id="灼铜赫铜息壤-三原料不满速固气机" tabindex="-1">灼铜赫铜息壤-三原料不满速固气机 <a class="header-anchor" href="#灼铜赫铜息壤-三原料不满速固气机" aria-label="Permalink to &quot;灼铜赫铜息壤-三原料不满速固气机&quot;">​</a></h3><p>加上禁区息壤气作为原料并不会让情况变得复杂，因为息壤气可以直接五比一分流</p><p><span id="source-block-R0yRbvDqSuO40bHFNIlyWX"></span></p><h2 id="重息壤气赫铜气-混用提纯机-前馈-反馈控制" tabindex="-1">重息壤气赫铜气 混用提纯机-前馈-反馈控制 <a class="header-anchor" href="#重息壤气赫铜气-混用提纯机-前馈-反馈控制" aria-label="Permalink to &quot;重息壤气赫铜气 混用提纯机-前馈-反馈控制&quot;">​</a></h2><p>还没有完全吃透细节，暂且搁置</p><p><span id="source-block-ZJVOO6eIEMkLMbQvKmSE1N"></span></p><h2 id="灼铜赫铜-混用不满速固气机-前后与馈-反馈控制" tabindex="-1">灼铜赫铜 混用不满速固气机-前后与馈-反馈控制 <a class="header-anchor" href="#灼铜赫铜-混用不满速固气机-前后与馈-反馈控制" aria-label="Permalink to &quot;灼铜赫铜 混用不满速固气机-前后与馈-反馈控制&quot;">​</a></h2><p>很酷的智能自适应产线</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4e5e84b5d041b1d0.q90-ed441470533d56e5.webp" alt="较简单的自适应装置们"></p><div class="logistics-image-caption" data-source-block="BRAbUyENxN6mouDw0bWYhW"><p>EF011I9oIIea9UO030O7</p></div><p><span class="mark-red">此蓝图存在问题，已过时</span></p><p>赫铜未满灼铜未满时一比二生产赫灼</p><p>赫铜已满灼铜未满时三核生产灼铜</p><p>赫铜未满灼铜已满时一核生产赫铜</p><p>全满了当然罢工了（用不掉的原料会积累），你还想怎的</p><p>如果灼铜满了赫铜满了之后使用了一些赫铜并不会自动复位，而是需要卖出灼铜后才会复位——事实上正是因为卖灼铜非常自然所以并没有进行灼铜的满仓检测而是依靠卖出复位。</p><p>从<a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a>抠出来的赫灼切换部分，蓝图码也在里面，可在模拟器运行 <a href="https://beta.enka.network/endfield/aic/?id=u1H0R2Z9b7A5U3" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=u1H0R2Z9b7A5U3</a></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0cf917bd5c203c43.q90-97e9bbab9418e2c2.webp" alt="较简单的自适应装置们"></p><p><span id="source-block-MPkNbUiCtrQPRpxKeiP4o5"></span></p><h2 id="息壤气-固气机-溢流式后馈" tabindex="-1">息壤气-固气机-溢流式后馈 <a class="header-anchor" href="#息壤气-固气机-溢流式后馈" aria-label="Permalink to &quot;息壤气-固气机-溢流式后馈&quot;">​</a></h2><p>kokobird：老大，我投个稿</p><p>未来科技佬的需求：上游供应18息壤气，下游需要的息壤气在18-48浮动，需要按需启停固气机</p><p>原理：外部供气首先进入循环回路，一支和其他任意流体混管，混管长度&gt;1格。其他流体流通时，会堵塞混管，息壤气先在储气罐中积累，然后溢流到固气机中开始正常工作，此时产量达到48.由于下游需求流量不足48，会逐渐堵塞，并最终堵住其他流体，使得左侧息壤可以两路通过，停止溢流，最终固气机停止工作，使产量回到18。产量又不足以满足下游需求量，因此其他流体在之后又开始流通，如此形成自适应震荡循环。</p><p>问题仍然是溢流式通病：启动慢，响应慢，周期长。设上游流量I，下游需求流量O’，实际需求总流量为O（O&#39;+(O&#39;-I)<em>1.25）。下游仓储C，启动大约需要500/(I/2)的时间，然后开始产息壤，在堵塞其他流体前总共经过C/(30+I-O)时间，如果太长，多口暗管会堵满C0息壤气，因此堵塞后恢复时间为C0</em>10(~5000s)，息壤气额外生产的息壤量高达C0<em>10(~5000s)</em>（30+I-O&#39;)，需要加比较大的缓存</p><p><a href="https://beta.enka.network/endfield/aic/?id=W2c5B3w8Z4U3t5" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=W2c5B3w8Z4U3t5</a></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f9efe8b718b26492.q90-009c4a7c970a51ce.webp" alt="较简单的自适应装置们"></p></div>',1)])])}const b=s(n,[["render",i]]);export{h as __pageData,b as default};
